    imageHint: "Matterhorn mountain peak from Italian side",
    descriptionAdvanced: {
      de: "Der Monte Cervino, im deutschsprachigen Raum als Matterhorn bekannt, ist einer der markantesten und bekanntesten Berge der Welt. Er liegt in den Walliser Alpen an der Grenze zwischen der italienischen Region Aostatal und dem Schweizer Kanton Wallis. Mit einer Höhe von 4478 Metern besticht er durch seine nahezu perfekte pyramidale Form, deren vier scharfe Grate in die Himmelsrichtungen zeigen. Die Erstbesteigung im Jahr 1865 durch Edward Whymper markierte das Ende des goldenen Zeitalters des Alpinismus und endete tragisch mit dem Tod von vier Bergsteigern. Auf der italienischen Seite liegt der bekannte Skiort Breuil-Cervinia, von dem aus zahlreiche Routen auf den Gipfel führen, wobei der Löwengrat der klassische Aufstieg ist. Der Berg besteht hauptsächlich aus Gneisen und Schiefern, die durch die Kollision der afrikanischen und europäischen Erdplatten emporgehoben wurden. Er bleibt ein Symbol für technische Herausforderung und natürliche Ästhetik im Hochgebirge.",
      hu: "A Monte Cervino, amely Matterhorn néven is világszerte ismert, az Alpok egyik legikonikusabb csúcsa, az olaszországi Valle d'Aosta és a svájci Wallis kanton határán található. A 4478 méter magas hegy jellegzetes, szinte tökéletes piramis alakjáról híres, amelynek négy oldala a négy égtáj felé néz. Geológiai szempontból a hegy különlegessége, hogy felső része az afrikai tektonikus lemez kőzeteiből áll, amely az európai lemezre tolódott fel. Az első sikeres megmászása 1865-ben történt Edward Whymper vezetésével, amely azonban tragédiába torkollott, négy hegymászó életét vesztette az ereszkedés során. Az olasz oldalon fekvő Breuil-Cervinia üdülőhely a hegymászók és síelők központja, ahonnan a Lyon-gerincen keresztül vezet az út a csúcsra. A Matterhorn nemcsak Olaszország és Svájc jelképe, hanem a modern alpinizmus szülőhelyének és legnagyobb kihívásának is tekintik.",
      ro: "Monte Cervino, cunoscut internațional sub numele de Matterhorn, este unul dintre cei mai emblematici munți din lume, situat la granița dintre Italia (Valle d'Aosta) și Elveția (Valais). Cu o altitudine de 4478 de metri, vârful se distinge prin forma sa piramidală aproape perfectă, având patru fețe orientate spre punctele cardinale. Din punct de vedere geologic, muntele este fascinant deoarece partea sa superioară este compusă din roci aparținând plăcii tectonice africane, împinse peste placa europeană. Prima ascensiune a fost realizată în 1865 de Edward Whymper, marcând un moment istoric dar tragic pentru alpinism, patru membri ai expediției pierzându-și viața la coborâre. Versantul italian este accesibil din stațiunea Breuil-Cervinia, oferind rute tehnice precum Creasta Leului. Monte Cervino rămâne o provocare majoră pentru alpiniști și un simbol al frumuseții brute a Alpilor Pennini, atrăgând anual mii de turiști și fotografi.",
      en: "Monte Cervino, widely known as the Matterhorn, is one of the most iconic and recognizable peaks in the world, straddling the border between Italy and Switzerland. Rising to 4478 meters in the Pennine Alps, it is famous for its nearly symmetrical pyramidal shape with four steep faces facing the cardinal points. Geologically, the mountain is an ophiolite, with its upper portion consisting of rock from the African tectonic plate pushed over the European plate during the Alpine orogeny. The first successful ascent took place in 1865 by Edward Whymper's team, an event that ended in tragedy when four climbers fell to their deaths. On the Italian side, the town of Breuil-Cervinia serves as the main gateway for climbers tackling the challenging Lion's Ridge. The Matterhorn remains a definitive symbol of high-altitude mountaineering and is a central figure in the cultural and sporting identity of the Western Alps.",
      es: "El Monte Cervino, conocido en el ámbito germanoparlante como Matterhorn, es una de las montañas más distintivas y famosas del mundo. Se sitúa en los Alpes Peninos, en la frontera entre la región italiana del Valle de Aosta y el cantón suizo del Valais. Con una altura de 4478 metros, impresiona por su forma piramidal casi perfecta, cuyas cuatro aristas apuntan a los puntos cardinales. La primera ascensión en 1865 por Edward Whymper marcó el final de la edad de oro del alpinismo y terminó trágicamente con la muerte de cuatro escaladores. En el lado italiano se encuentra la conocida estación de esquí de Breuil-Cervinia, desde donde parten numerosas rutas hacia la cima, siendo la Cresta del León el ascenso clásico. La montaña se compone principalmente de gneis y esquistos, que fueron elevados por la colisión de las placas tectónicas africana y europea. Sigue siendo un símbolo de desafío técnico y estética natural en la alta montaña.",
      pt: "O Monte Cervino, conhecido nos países de língua alemã como Matterhorn, é uma das montanhas mais marcantes e famosas do mundo. Localiza-se nos Alpes Peninos, na fronteira entre a região italiana do Vale de Aosta e o cantão suíço de Valais. Com uma altitude de 4478 metros, impressiona pela sua forma piramidal quase perfeita, cujas quatro arestas apontam para os pontos cardeais. A primeira ascensão em 1865 por Edward Whymper marcou o fim da era de ouro do alpinismo e terminou tragicamente com a morte de quatro alpinistas. Do lado italiano encontra-se a conhecida estância de esqui de Breuil-Cervinia, de onde partem numerosas rotas para o cume, sendo a aresta do Leão a subida clássica. A montanha é composta principalmente por gnaisses e xistos, que foram elevados pela colisão das placas tectónicas africana e europeia. Continua a ser um símbolo de desafio técnico e estética natural na alta montanha.",
      fr: "Le Monte Cervino, connu sous le nom de Cervin en français et Matterhorn en allemand, est l'une des montagnes les plus emblématiques et célèbres au monde. Il se situe dans les Alpes valaisannes, à la frontière entre la région italienne de la Vallée d'Aoste et le canton suisse du Valais. Avec une altitude de 4478 mètres, il se distingue par sa forme pyramidale presque parfaite, dont les quatre arêtes font face aux points cardinaux. La première ascension en 1865 par Edward Whymper marqua la fin de l'âge d'or de l'alpinisme et se termina tragiquement par la mort de quatre grimpeurs. Du côté italien se trouve la célèbre station de ski de Breuil-Cervinia, point de départ de nombreux itinéraires vers le sommet, l'arête du Lion étant la voie classique. La montagne est principalement composée de gneiss et de schistes, soulevés par la collision des plaques tectoniques africaine et européenne. Il reste un symbole de défi technique et d'esthétique naturelle en haute montagne.",
    },
