    imageHint: "Monte Viso pyramid peak",
    descriptionAdvanced: {
      de: "Der Monte Viso, auch Monviso genannt, ist mit 3841 Metern der höchste Gipfel der Cottischen Alpen im Nordwesten Italiens. Er überragt seine Nachbargipfel um mehr als 500 Meter und ist aufgrund seiner isolierten Lage und markanten Form bereits aus großer Entfernung, sogar aus der Po-Ebene, deutlich sichtbar. Geographisch und kulturell ist er von enormer Bedeutung, da an seinem Fuße, im Pian del Re auf 2020 Metern Höhe, der Po, der längste Fluss Italiens, entspringt. Der Berg besteht vorwiegend aus Grüngesteinen wie Eklogit, die Zeugnis von uralten Ozeanböden ablegen, die bei der Alpenfaltung emporgehoben wurden. Die Erstbesteigung gelang 1861 dem Engländer William Mathews. Heute ist der Monviso das Zentrum eines grenzüberschreitenden Biosphärenreservats der UNESCO, das den Schutz der einzigartigen alpinen Flora und Fauna gewährleistet. Er gilt als Wahrzeichen des Piemont und ist ein beliebtes Ziel für erfahrene Alpinisten und Wanderer.",
      hu: "A Monte Viso, vagy röviden Monviso, a Cotti-Alpok legmagasabb csúcsa Észak-Olaszországban, Piemont régióban, magassága 3841 méter. Különlegessége, hogy környezetéből jóval kiemelkedik, így tiszta időben már a Pó-síkság távolabbi pontjairól, sőt Nizza környékéről is jól látható jellegzetes piramis alakja. Történelmi és földrajzi jelentőségét növeli, hogy a lábánál, a Pian del Re területén ered Olaszország leghosszabb folyója, a Pó. A hegy anyaga főként eklogit és más metamorf kőzetek, amelyek egy ősi óceáni aljzat megmaradt darabjai. Első megmászása 1861-ben történt William Mathews által, ami fontos mérföldkő volt a nyugati alpinizmusban. 2013 óta a hegy és környezete az UNESCO bioszféra-rezervátumának része, amely kiemelt figyelmet fordít a helyi ökoszisztémák megőrzésére. A Monviso körüli többnapos túraútvonal, a Giro del Viso, az egyik legszebb magashegyi túra Európában.",
      ro: "Monte Viso, supranumit și Monviso, este cel mai înalt vârf din Alpii Cotici, atingând o altitudine de 3841 de metri în regiunea Piemont. Datorită izolării sale relative față de alte vârfuri de înălțime similară, silueta sa piramidală este vizibilă de la mari distanțe, dominând orizontul Câmpiei Padului. Acest munte are o importanță simbolică și geografică majoră, deoarece la poalele sale, în localitatea Pian del Re, se află izvorul râului Pad, cel mai lung râu din Italia. Geologic, muntele este format din roci magmatice și metamorfice care provin din fundul unui ocean preistoric, ridicat în timpul orogenezei alpine. Prima ascensiune documentată a avut loc în 1861. În prezent, zona face parte dintr-o rezervație transfrontalieră a biosferei UNESCO, protejând un ecosistem alpin fragil și divers. Traseul circular 'Giro del Viso' este extrem de popular printre drumeții care doresc să admire muntele din toate perspectivele.",
      en: "Monte Viso, often called Monviso, is the highest peak in the Cottian Alps of Northwest Italy, reaching an elevation of 3841 meters. Because it rises over 500 meters above any surrounding peaks, its distinct pyramid silhouette is visible from across the Po Valley and even as far as the French Riviera. A site of immense geographic importance, its base at Pian del Re (2020 m) is the official source of the Po River, Italy's longest waterway. The mountain is primarily composed of eclogite, a dense metamorphic rock formed from ancient oceanic crust subducted and then uplifted during the creation of the Alps. The first ascent was recorded in 1861 by William Mathews. Today, the mountain is the centerpiece of a UNESCO Cross-Border Biosphere Reserve between Italy and France, recognized for its exceptional alpine biodiversity. The 'Giro del Viso' is a classic multi-day trekking route that circles the massif, offering stunning views of the 'King of Stone'.",
      es: "El Monte Viso, también llamado Monviso, es con sus 3.841 metros la cima más alta de los Alpes Cocios en el noroeste de Italia. Supera a sus picos vecinos en más de 500 metros y, debido a su ubicación aislada y su forma distintiva, es claramente visible desde grandes distancias, incluso desde la llanura del Po. Geográfica y culturalmente es de enorme importancia, ya que a sus pies, en el Pian del Re a 2.020 metros de altitud, nace el Po, el río más largo de Italia. La montaña se compone principalmente de rocas verdes como la eclogita, que son testimonio de antiguos fondos oceánicos elevados durante el plegamiento alpino. La primera ascensión fue lograda en 1861 por el inglés William Mathews. Hoy en día, el Monviso es el centro de una Reserva de la Biosfera transfronteriza de la UNESCO, que garantiza la protección de la flora y fauna alpina únicas. Se considera el emblema del Piamonte y es un destino popular para alpinistas experimentados y excursionistas.",
      pt: "O Monte Viso, também chamado de Monviso, é com 3.841 metros o pico mais alto dos Alpes Cócios, no noroeste da Itália. Ele se destaca sobre os picos vizinhos por mais de 500 metros e, devido à sua localização isolada e forma marcante, é claramente visível de grandes distâncias, até mesmo da Planície Padana. Geograficamente e culturalmente, possui uma enorme importância, pois a seus pés, no Pian del Re a 2.020 metros de altitude, nasce o Pó, o rio mais longo da Itália. A montanha consiste predominantemente em rochas verdes, como o eclogito, que testemunham antigos fundos oceânicos elevados durante a formação dos Alpes. A primeira ascensão foi realizada em 1861 pelo inglês William Mathews. Hoje, o Monviso é o centro de uma reserva da biosfera transfronteiriça da UNESCO, que garante a proteção da flora e fauna alpinas únicas. É considerado o símbolo do Piemonte e um destino popular para alpinistas experientes e caminhantes.",
      fr: "Le Monte Viso, également appelé Monviso, est avec ses 3 841 mètres le point culminant des Alpes Cottiennes dans le nord-ouest de l'Italie. Il domine ses sommets voisins de plus de 500 mètres et, en raison de sa position isolée et de sa forme caractéristique, il est nettement visible de très loin, même depuis la plaine du Pô. Géographiquement et culturellement, il revêt une importance énorme car à son pied, au Pian del Re à 2 020 mètres d'altitude, prend sa source le Pô, le plus long fleuve d'Italie. La montagne est principalement composée de roches vertes comme l'éclogite, témoignages d'anciens fonds océaniques soulevés lors de l'orogenèse alpine. La première ascension a été réussie en 1861 par l'Anglais William Mathews. Aujourd'hui, le Monviso est le centre d'une réserve de biosphère transfrontalière de l'UNESCO, qui assure la protection de la flore et de la faune alpines uniques. Il est considéré comme l'emblème du Piémont et constitue une destination prisée pour les alpinistes expérimentés et les randonneurs.",
    },
