      en: ["Elevation of 3841 meters", "Source of the Po River at its base", "First successful ascent in 1861", "UNESCO Biosphere Reserve since 2013", "Visible from the Mediterranean on clear days", "Highest peak in the Cottian Alps"],
      es: ["Altitud de 3.841 metros", "Fuente del río Po a sus pies", "Primera ascensión en el año 1861", "Reserva de la Biosfera de la UNESCO desde 2013", "Compuesto por rocas de un antiguo fondo oceánico", "Montaña más alta de los Alpes Cocios"],
      pt: ["Altitude de 3.841 metros", "Nascente do rio Pó a seus pés", "Primeira ascensão no ano de 1861", "Reserva da Biosfera da UNESCO desde 2013", "Composto por rochas de um antigo fundo oceânico", "Montanha mais alta dos Alpes Cócios"],
      fr: ["Altitude de 3 841 mètres", "Source du fleuve Pô à ses pieds", "Première ascension en 1861", "Réserve de biosphère de l'UNESCO depuis 2013", "Composé de roches d'un ancien fond océanique", "Plus haute montagne des Alpes Cottiennes"],
