      es: ["Superficie de unos 47.000 kilómetros cuadrados", "La llanura más grande del sur de Europa", "Formada por sedimentación fluvial", "Centro económico de Italia", "Principal zona de cultivo de arroz en Europa", "Limitada por los Alpes y los Apeninos"],
