      fr: ["Superficie d'environ 47 000 kilomètres carrés", "Plus grande plaine d'Europe du Sud", "Formée par la sédimentation fluviale", "Centre économique de l'Italie", "Principale zone de culture du riz en Europe", "Bordée par les Alpes et les Apennins"],
