      en: ["Summit reaches an elevation of 4061 meters", "Only 4000m peak entirely in Italy", "National Park established in 1922", "Crucial refuge for the Alpine ibex", "Composed primarily of metamorphic gneiss", "Home to several retreating glaciers"],
