      pt: ["Pico mais alto a 4.061 metros", "Único quatro mil inteiramente em Itália", "Parque Nacional desde 1922", "Local de salvamento do íbex-dos-alpes", "Composto predominantemente por gnaisse", "Glaciares importantes como o Tribolazione"],
