      es: ["Altura: 1.701 metros", "Región: Marcas", "Zona de senderismo", "Roca caliza"],
      pt: ["Altitude: 1.701 metros", "Região: Marcas", "Área de caminhadas", "Rocha calcária"],
      fr: ["Altitude : 1 701 mètres", "Région : Marches", "Zone de randonnée", "Roche calcaire"],
