      es: ["Altura: 1.589 metros", "Región: Toscana", "Cumbre panorámica", "Yacimientos de mármol"],
      pt: ["Altitude: 1.589 metros", "Região: Toscana", "Pico panorâmico", "Depósitos de mármore"],
      fr: ["Altitude : 1 589 mètres", "Région : Toscane", "Sommet panoramique", "Gisements de marbre"],
